def main():
    os.makedirs(DATA_DIR, exist_ok=True)
    conn = sqlite3.connect(DB_PATH) if os.path.exists(DB_PATH) else None

    processed_list = []
    seen = set()

    for item in RAW_GOETHE_A1:
        hw, pos, art, cat, en, ex_de, ex_en, diff = item
        clean_hw = hw.strip()
        key = (clean_hw.lower(), pos)
        if key in seen:
            continue
        seen.add(key)

        # Verify or enhance article from database if available
        if conn and pos == "noun" and not art:
            cur = conn.execute("SELECT article FROM entries WHERE headword = ? AND part_of_speech = 'noun' AND article IS NOT NULL LIMIT 1", (clean_hw,))
            row = cur.fetchone()
            if row and row[0]:
                art = row[0]

        entry = {
            "headword": clean_hw,
            "part_of_speech": pos,
            "article": art,
            "category": cat,
            "english": en,
            "example_de": ex_de,
            "example_en": ex_en,
            "base_difficulty": diff,
            "is_goethe_a1": True
        }
        processed_list.append(entry)

    if conn:
        conn.close()

    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        json.dump(processed_list, f, ensure_ascii=False, indent=2)

    print(f"Successfully generated {len(processed_list)} canonical Goethe A1 vocabulary words into:")
    print(f"  {OUTPUT_PATH}")

if __name__ == "__main__":
    main()
